+  last_user_id bigint;
+  batch_start bigint;
   batch_end bigint;
+  users_in_batch integer;
   rows_updated bigint;
 BEGIN
@@
-  SELECT min(id), max(id)
-  INTO min_user_id, max_user_id
-  FROM users;
-
-  IF min_user_id IS NULL THEN
-    RETURN;
-  END IF;
-
-  batch_start := min_user_id;
-
-  WHILE batch_start <= max_user_id LOOP
-    batch_end := batch_start + batch_size - 1;
+  last_user_id := NULL;
+
+  LOOP
+    SELECT min(id), max(id), count(*)::integer
+    INTO batch_start, batch_end, users_in_batch
+    FROM (
+      SELECT id
+      FROM users
+      WHERE last_user_id IS NULL OR id > last_user_id
+      ORDER BY id
+      LIMIT batch_size
+    ) batch_ids;
+
+    EXIT WHEN users_in_batch = 0;
@@
-    batch_start := batch_end + 1;
+    last_user_id := batch_end;
   END LOOP;
 END;
 $$;
